
clc;
clear;
close all;

%%\ 1. STUDENT DATA

% Columns represent:
% [Maths, Science, English, Attendance]

data = [
    85  78  90  95;
    72  68  75  80;
    90  88  92  98;
    65  70  68  72;
    78  82  80  85;
    88  90  85  96;
    55  60  58  65;
    92  95  94  99;
    70  75  72  78;
    80  85  82  90;
    60  65  62  70;
    95  92  96  100;
    75  72  78  82;
    68  70  65  75;
    86  84  88  94;
    73  76  74  80;
    82  80  85  89;
    58  62  60  68;
    91  89  93  97;
    77  79  81  86
];

% Extracting columns
maths = data(:,1);
science = data(:,2);
english = data(:,3);
attendance = data(:,4);

% Calculate average examination marks
marks = mean(data(:,1:3), 2);

fprintf('\nSTUDENT PERFORMANCE ANALYSIS\n'); %[output:6a484c30]
fprintf('-----------------------------\n'); %[output:5e3a84c9]

%%\ 2. STATISTICAL CALCULATIONS

fprintf('\nSTATISTICAL SUMMARY\n'); %[output:06e7d8f1]

subjects = {'Maths','Science','English'};

subjectData = [maths science english];

for i = 1:3 %[output:group:2e9637fb]

    x = subjectData(:,i);

    fprintf('\n%s:\n', subjects{i}); %[output:03850f70] %[output:01f30f31] %[output:59160301]

    fprintf('Mean = %.2f\n', mean(x)); %[output:57446922] %[output:8cf8db66] %[output:89c51ea9]
    fprintf('Median = %.2f\n', median(x)); %[output:69ca8dc3] %[output:3928507e] %[output:506cb9f3]
    fprintf('Mode = %.2f\n', mode(x)); %[output:52c978a0] %[output:71911e4e] %[output:44112206]
    fprintf('Range = %.2f\n', range(x)); %[output:1008a644] %[output:31e9c410] %[output:7bbbe630]
    fprintf('Variance = %.2f\n', var(x)); %[output:5acb13d8] %[output:98365cbe] %[output:4e63cf36]
    fprintf('Standard Deviation = %.2f\n', std(x)); %[output:3dbbed56] %[output:62f3e28c] %[output:45ca70fc]

end %[output:group:2e9637fb]

%%\ 3. CORRELATION BETWEEN ATTENDANCE AND MARKS

correlation = corrcoef(attendance, marks);

r = correlation(1,2);

fprintf('\nCORRELATION ANALYSIS\n'); %[output:413488a5]
fprintf('Correlation Coefficient = %.4f\n', r); %[output:71af1aaf]

figure; %[output:10234537]

scatter(attendance, marks, 70, 'filled'); %[output:10234537]

xlabel('Attendance (%)'); %[output:10234537]
ylabel('Average Examination Marks'); %[output:10234537]

title('Attendance vs Examination Marks'); %[output:10234537]

grid on; %[output:10234537]

%%\ 4. LINEAR REGRESSION

% Regression equation:
% Marks = m * Attendance + c

p = polyfit(attendance, marks, 1);

predictedMarks = polyval(p, attendance);

fprintf('\nLINEAR REGRESSION\n'); %[output:394f128f]

fprintf('Slope = %.4f\n', p(1)); %[output:87d1d84e]
fprintf('Intercept = %.4f\n', p(2)); %[output:1e3f7240]

% Predict marks for new attendance values
newAttendance = [70; 80; 90; 95];

futureMarks = polyval(p, newAttendance);

fprintf('\nPREDICTED MARKS\n'); %[output:16bdc3f3]

for i = 1:length(newAttendance) %[output:group:99fc3e0f]

    fprintf('Attendance %.0f%% = Predicted Marks %.2f\n', ... %[output:55df1079]
        newAttendance(i), futureMarks(i)); %[output:55df1079]

end %[output:group:99fc3e0f]

% Regression graph

figure; %[output:5d99f115]

scatter(attendance, marks, 70, 'filled'); %[output:5d99f115]

hold on; %[output:5d99f115]

plot(attendance, predictedMarks, 'r-', ... %[output:5d99f115]
    'LineWidth', 2); %[output:5d99f115]

xlabel('Attendance (%)'); %[output:5d99f115]
ylabel('Average Marks'); %[output:5d99f115]

title('Linear Regression'); %[output:5d99f115]

legend('Actual Marks','Regression Line'); %[output:5d99f115]

grid on; %[output:5d99f115]

%%\ 5. HYPOTHESIS TESTING (T-TEST)

% Divide students into two groups
% Group A: First 10 students
% Group B: Remaining 10 students

groupA = marks(1:10);
groupB = marks(11:20);

% Hypotheses:
% H0: Both groups have equal mean performance
% H1: Both groups have different mean performance

[h, pValue, ci, stats] = ttest2(groupA, groupB);

fprintf('\nHYPOTHESIS TESTING\n'); %[output:7e536e22]

fprintf('Group A Mean = %.2f\n', mean(groupA)); %[output:909d14fe]
fprintf('Group B Mean = %.2f\n', mean(groupB)); %[output:40d4926d]

fprintf('T-Statistic = %.4f\n', stats.tstat); %[output:5c94aff5]
fprintf('P-Value = %.4f\n', pValue); %[output:53c0600d]

if h == 1 %[output:group:56f0245f]

    fprintf('Result: Significant difference exists.\n');

else

    fprintf('Result: No significant difference exists.\n'); %[output:2c7514f0]

end %[output:group:56f0245f]

%%\ 6. GROUP COMPARISON GRAPH

figure; %[output:91f97b50]

bar([mean(groupA), mean(groupB)]); %[output:91f97b50]

set(gca, 'XTickLabel', {'Group A','Group B'}); %[output:91f97b50]

ylabel('Average Marks'); %[output:91f97b50]

title('Performance Comparison Between Groups'); %[output:91f97b50]

grid on; %[output:91f97b50]

%%\ 7. PERFORMANCE REPORT

fprintf('\nFINAL PERFORMANCE REPORT\n'); %[output:321a1e70]
fprintf('------------------------\n'); %[output:87938186]

fprintf('Total Students = %d\n', length(marks)); %[output:29a82db4]

fprintf('Overall Average Marks = %.2f\n', mean(marks)); %[output:1846f12a]

fprintf('Highest Marks = %.2f\n', max(marks)); %[output:00dd3421]

fprintf('Lowest Marks = %.2f\n', min(marks)); %[output:499dcd9a]

fprintf('Average Attendance = %.2f%%\n', mean(attendance)); %[output:38dec103]

fprintf('Attendance-Marks Correlation = %.4f\n', r); %[output:44b5b39e]

if mean(marks) >= 75 %[output:group:67cff8c7]

    fprintf('Overall Performance: Excellent\n'); %[output:220a0845]

elseif mean(marks) >= 60

    fprintf('Overall Performance: Good\n');

else

    fprintf('Overall Performance: Needs Improvement\n');

end %[output:group:67cff8c7]

fprintf('\nPROJECT EXECUTION COMPLETED!\n'); %[output:26a07191]


